{
  global:
    # Bare / Node-API runtime entry points (required for the .bare module).
    bare_*;
    napi_*;
    js_*;

    # llama.cpp public C API.
    llama_*;
    llava_*;
    mtmd_*;

    # llama.cpp build-info globals (from llama::llama-common-base, formerly
    # llama::build_info), e.g. LLAMA_BUILD_NUMBER / LLAMA_COMMIT, referenced by
    # llama-common.
    LLAMA_*;

    # ggml public C API (also consumed by the dlopen'd backend .so files at
    # runtime via ggml_backend_load_all_from_path, which resolve these symbols
    # from this single loaded module).
    ggml_*;
    gguf_*;

    # C++-linkage symbols consumed by the addons. Matched against *demangled*
    # names, so the patterns are the source-level names (no _Z mangling).
    # Patterns must stay unquoted: quoting would turn them into literal
    # (non-wildcard) symbol names.
    #
    #  - common_* / json_schema_to_grammar: libcommon helpers (common_tokenize,
    #    common_sampler_*, common_chat_*, ...).
    #  - llama_* / llava_* / mtmd_*: the qvac-fabric fork adds C++-linkage
    #    extensions alongside the stock C API (e.g. llama_model_meta_from_file,
    #    which takes a std::unique_ptr). The C patterns above only cover the
    #    extern "C" entry points, so these must be listed here as well.
    #  - gguf_*: same rationale for the gguf helpers.
    extern "C++" {
      common_*;
      json_schema_to_grammar*;
      llama_*;
      llava_*;
      mtmd_*;
      gguf_*;
      ggml_*;
      # Free helpers declared in common.h / qvac-fabric extensions that do not
      # share the common_ prefix (e.g. string_format, the cpu_params helpers and
      # the llama_metadata_handle deleter).
      string_*;
      set_process_priority*;
      postprocess_cpu_params*;
      metadata_handle_deleter*;
    };

    # --- The C++ runtime ------------------------------------------------------
    # Fabric owns the one C++ runtime in the process on Linux, and exports the
    # Itanium C++ ABI here so consumer addons can import it. They must, because
    # RTTI compares typeinfo by *address*: when fabric and an addon each
    # statically linked their own libc++, each carried its own copy of every
    # std:: typeinfo, so an exception thrown by libcommon inside fabric matched
    # no `catch (const std::exception&)` in the addon. Argument-validation
    # errors fell through to JSCATCH's catch-all and reached JS as "Unknown
    # error" instead of llama's message. Addon modules now link with
    # -nostdlib++ and resolve all of this from here — see
    # qvac_addon_import_fabric_cxx_runtime in cmake/qvac-addon/qvac-addon.cmake
    # and arch/qips/linux-fabric-libcxx-ownership.md.
    #
    # Every pattern here is matched against the MANGLED name, outside the
    # extern "C++" block above. That is deliberate and load-bearing: demangled
    # matching cannot express this set. "typeinfo for std::exception" and
    # "operator new(unsigned long)" have no usable prefix, and a demangled
    # function template carries its return type first, so `std::*` silently
    # misses `void std::__1::__sort<...>(...)` and every other out-of-line
    # template instantiation an addon needs. libc++ mangles all of it under
    # `St` (std) because every entity lives in the inline ABI namespace
    # std::__1, which is what makes the prefixes below both complete and tight.
    #
    # Exception allocation / throw / catch / rethrow, static-init guards,
    # thread-local destructor registration and the demangler.
    __cxa_*;
    # dynamic_cast's runtime helper.
    __dynamic_cast;
    # The personality routine the unwinder calls into, plus the unwinder API
    # itself (libc++abi links one in; if the toolchain uses libgcc_s instead,
    # fabric defines none of these and the pattern matches nothing).
    _Unwind_*;
    __gxx_personality_v0;
    # typeinfo (_ZTI), typeinfo names (_ZTS), vtables (_ZTV) and the VTT /
    # covariant-thunk variants, for the std:: hierarchy and every other type
    # fabric defines. Exporting the typeinfo objects is what makes a
    # cross-module `catch` match at all.
    _ZT*;
    # operator new / operator delete, including the sized, aligned and nothrow
    # overloads. One definition per process keeps an allocation made inside
    # fabric matched with the delete that frees it in the addon.
    _Znw*;
    _Zna*;
    _Zdl*;
    _Zda*;
    # The standard library itself: out-of-line members and template
    # instantiations (_ZNSt / _ZNKSt for const members, _ZNVSt / _ZNRSt for the
    # volatile and ref-qualified ones), free functions in std (_ZSt, which
    # covers the iostream globals and the std::__throw_* helpers), and the guard
    # variables for function-local statics inside them.
    _ZNSt*;
    _ZNKSt*;
    _ZNVSt*;
    _ZNRSt*;
    _ZSt*;
    _ZGVNSt*;

  local:
    *;
};
